package botcomm

import (
	"context"
	"encoding/json"
	"fmt"
	"net/http"
	"time"
)

// LinkPreview is optional article metadata generated by the server.
type LinkPreview struct {
	URL         string        `json:"url"`
	SiteName    string        `json:"siteName"`
	Title       string        `json:"title"`
	Description string        `json:"description,omitempty"`
	Image       *PreviewImage `json:"image,omitempty"`
}

type PreviewImage struct {
	ID     string `json:"id"`
	Width  int    `json:"width"`
	Height int    `json:"height"`
}

type MessageStream struct {
	Status    string    `json:"status"`
	Sequence  int64     `json:"sequence"`
	UpdatedTS time.Time `json:"updatedTS"`
}

type StreamInput struct {
	Content  string `json:"content"`
	Sequence int64  `json:"sequence"`
	Status   string `json:"status"`
}

// Message is a single chat message, as returned by the API.
type Message struct {
	Stream           *MessageStream    `json:"stream,omitempty"`
	Reactions        map[string]string `json:"reactions,omitempty"`
	ReactionRevision int64             `json:"reactionRevision,omitempty"`

	Card      *AgentCard     `json:"card,omitempty"`
	Fields    map[string]any `json:"fields,omitempty"`
	Cancel    bool           `json:"cancel,omitempty"`
	ID        string         `json:"id"`
	SessionID string         `json:"sessionID"`
	AuthorID  string         `json:"authorID"`

	Command  string `json:"-"` // matched value when ArgumentCommands is enabled
	Argument string `json:"-"` // trimmed input; Content remains unchanged

	LinkPreview *LinkPreview `json:"linkPreview,omitempty"`
	PreviewTS   *time.Time   `json:"previewTS,omitempty"`

	Content  string          `json:"content"`
	Subject  string          `json:"subject,omitempty"`
	Metadata json.RawMessage `json:"metadata,omitempty"`

	// Keyboard is present on bot messages sent with one-tap answer options.
	Keyboard    *Keyboard    `json:"keyboard,omitempty"`
	Attachments []Attachment `json:"attachments,omitempty"`
	// ReplyTo and Value are set on a user's answer to a keyboard message:
	// ReplyTo is the id of the keyboard message, Value the machine value of
	// the chosen option (Content carries its human-readable label).
	ReplyTo string `json:"replyTo,omitempty"`
	Value   string `json:"value,omitempty"`

	Silent    bool `json:"silent"`
	Read      bool `json:"read"`
	Delivered bool `json:"delivered"`

	AuthorTS time.Time  `json:"authorTS"`
	CreateTS time.Time  `json:"createTS"`
	EditTS   *time.Time `json:"editTS,omitempty"`
}

// KeyboardOption is one tappable choice offered by a keyboard: Label is shown
// to the user, Value is what the bot receives when it is chosen.
type KeyboardOption struct {
	Label string `json:"label"`
	Value string `json:"value"`
}

// Keyboard is a set of one-tap answer options attached to a message. The
// server stamps Selected once the user answers; clients render an answered
// keyboard unclickable.
type Keyboard struct {
	Options  []KeyboardOption `json:"options"`
	Selected *string          `json:"selected,omitempty"`
}

// SendOptions configures an optional subject, keyboard, attachments and push suppression.
type SendOptions struct {
	Stream      bool            `json:"stream,omitempty"`
	Subject     string          `json:"subject,omitempty"`
	Metadata    json.RawMessage `json:"metadata,omitempty"`
	Keyboard    *Keyboard       `json:"keyboard,omitempty"`
	Attachments []string        `json:"attachments,omitempty"`
	Silent      bool            `json:"silent"`
}

// EditOptions changes only non-nil fields. An empty Subject clears it.
// Metadata is a JSON object (up to 4096 bytes); json.RawMessage("null") clears it.
type EditOptions struct {
	Content  *string         `json:"content,omitempty"`
	Subject  *string         `json:"subject,omitempty"`
	Metadata json.RawMessage `json:"metadata,omitempty"`
	Keyboard *Keyboard       `json:"keyboard,omitempty"`
}

// Send posts a message into a session and returns it as stored.
func (b *Bot) Send(ctx context.Context, sessionID, content string, silent ...bool) (*Message, error) {
	return b.SendWithOptions(ctx, sessionID, content, SendOptions{Silent: len(silent) > 0 && silent[0]})
}

// SendWithOptions posts a message with an optional subject, keyboard or attachments.
func (b *Bot) SendWithOptions(ctx context.Context, sessionID, content string, options SendOptions) (*Message, error) {
	return b.SendMessage(ctx, sessionID, MessageInput{Stream: options.Stream, Content: content, Subject: options.Subject, Metadata: options.Metadata, Keyboard: options.Keyboard, Attachments: options.Attachments, Silent: options.Silent})
}

func (b *Bot) postMessage(ctx context.Context, path string, req any) (*Message, error) {
	msg := &Message{}
	if err := b.do(ctx, http.MethodPost, path, req, msg); err != nil {
		return nil, fmt.Errorf("failed to send message: %w", err)
	}

	return msg, nil
}

// Typing shows a typing indicator to the user for a few seconds; call it again
// every 3-4s while a long reply is being prepared.
func (b *Bot) Typing(ctx context.Context, sessionID string) error {
	if err := b.do(ctx, http.MethodPost, fmt.Sprintf("/session/%s/typing", sessionID), nil, nil); err != nil {
		return fmt.Errorf("failed to send typing: %w", err)
	}

	return nil
}

// Edit replaces the content of a message the bot sent. A non-nil options slice
// also replaces the keyboard (409 once the user has answered the old one).
func (b *Bot) Edit(ctx context.Context, sessionID, messageID, content string, options ...KeyboardOption) (*Message, error) {
	req := EditOptions{Content: &content}
	if options != nil {
		req.Keyboard = &Keyboard{Options: options}
	}

	return b.EditWithOptions(ctx, sessionID, messageID, req)
}

// EditWithOptions changes content, subject or keyboard without changing other fields.
func (b *Bot) EditWithOptions(ctx context.Context, sessionID, messageID string, options EditOptions) (*Message, error) {
	return b.UpdateMessage(ctx, sessionID, messageID, MessageUpdate{Content: options.Content, Subject: options.Subject, Metadata: options.Metadata, Keyboard: options.Keyboard})
}

// Delete removes a message the bot sent.
func (b *Bot) Delete(ctx context.Context, sessionID, messageID string) error {
	if err := b.do(ctx, http.MethodDelete, fmt.Sprintf("/session/%s/message/%s", sessionID, messageID), nil, nil); err != nil {
		return fmt.Errorf("failed to delete message: %w", err)
	}

	return nil
}

// SendKeyboard posts a message with one-tap answer options. The user's tap
// arrives on the Messages channel as a message whose Content is the chosen
// option's Label, with ReplyTo set to the keyboard message's id and Value to
// the option's Value (a Value matching a registered command is routed to the
// Commands channel instead).
func (b *Bot) SendKeyboard(ctx context.Context, sessionID, content string, options []KeyboardOption) (*Message, error) {
	return b.SendWithOptions(ctx, sessionID, content, SendOptions{Keyboard: &Keyboard{Options: options}})
}

type MessageInput struct {
	IdempotencyKey string          `json:"-"`
	Stream         bool            `json:"stream,omitempty"`
	Content        string          `json:"content,omitempty"`
	Subject        string          `json:"subject,omitempty"`
	Metadata       json.RawMessage `json:"metadata,omitempty"`
	Actions        []Action        `json:"actions,omitempty"`
	Card           *AgentCard      `json:"card,omitempty"`
	Keyboard       *Keyboard       `json:"keyboard,omitempty"`
	Attachments    []string        `json:"attachments,omitempty"`
	Silent         bool            `json:"silent"`
	TS             time.Time       `json:"ts"`
}

type MessageUpdate struct {
	Content  *string         `json:"content,omitempty"`
	Subject  *string         `json:"subject,omitempty"`
	Metadata json.RawMessage `json:"metadata,omitempty"`
	Actions  []Action        `json:"actions,omitempty"`
	Card     *CardUpdate     `json:"card,omitempty"`
	Keyboard *Keyboard       `json:"keyboard,omitempty"`
}

func (b *Bot) SendMessage(ctx context.Context, sessionID string, input MessageInput) (*Message, error) {
	if input.Card != nil {
		if err := validateCardTaskStatuses(input.Card.Tasks); err != nil {
			return nil, err
		}
	}

	if input.TS.IsZero() {
		input.TS = time.Now()
	}

	return b.postMessage(ctx, fmt.Sprintf("/session/%s/message", sessionID), input)
}

func (b *Bot) UpdateMessage(ctx context.Context, sessionID, messageID string, change MessageUpdate) (*Message, error) {
	if change.Card != nil && change.Card.Tasks != nil {
		if err := validateCardTaskStatuses(*change.Card.Tasks); err != nil {
			return nil, err
		}
	}

	return b.postMessage(ctx, fmt.Sprintf("/session/%s/message/%s", sessionID, messageID), change)
}

func (b *Bot) GetMessage(ctx context.Context, sessionID, messageID string) (*Message, error) {
	result := &Message{}
	if err := b.do(ctx, http.MethodGet, fmt.Sprintf("/session/%s/message/%s", sessionID, messageID), nil, result); err != nil {
		return nil, err
	}

	return result, nil
}

// RecentMessages returns up to the last 10 messages in a session, newest first.
func (b *Bot) RecentMessages(ctx context.Context, sessionID string) ([]*Message, error) {
	var page struct {
		List []*Message `json:"list"`
	}
	if err := b.do(ctx, http.MethodGet, fmt.Sprintf("/session/%s/message?limit=10", sessionID), nil, &page); err != nil {
		return nil, err
	}

	return page.List, nil
}

// StartStream creates one live bubble. Update it with accumulated text snapshots.
func (b *Bot) StartStream(ctx context.Context, sessionID string) (*Message, error) {
	return b.SendMessage(ctx, sessionID, MessageInput{Stream: true})
}

// UpdateStream uses increasing sequence numbers; retry an identical snapshot safely.
// Batch updates at 500ms intervals and finish with status completed or failed.
func (b *Bot) UpdateStream(ctx context.Context, sessionID, messageID string, input StreamInput) (*Message, error) {
	return b.postMessage(ctx, fmt.Sprintf("/session/%s/message/%s/stream", sessionID, messageID), input)
}

// React replaces the bot's reaction; an empty emoji removes it.
func (b *Bot) React(ctx context.Context, sessionID, messageID, emoji string) (*Message, error) {
	return b.postMessage(ctx, fmt.Sprintf("/session/%s/message/%s/reaction", sessionID, messageID), map[string]string{"emoji": emoji})
}
